<?php declare(strict_types=1);namespace App\Models;final class Invoice extends Model{protected static string $table='invoices';protected static array $json=['lines','billing','seller'];protected static bool $timestamps=false;public static function forUser(int $M):array{return static::castAll(static::query()->where('user_id',$M)->orderBy('id','DESC')->get());}public static function forOrder(int $b):?array{return static::findBy('order_id',$b);}}